'use strict';
const $=s=>document.querySelector(s),esc=Office.xml;
const icons={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',units:'<path d="M4 21V5l8-3 8 3v16M2 21h20M9 21v-5h6v5M8 7h2m4 0h2M8 11h2m4 0h2"/>',guests:'<circle cx="9" cy="7" r="4"/><path d="M2 21v-3a7 7 0 0 1 14 0v3m1-18a4 4 0 0 1 0 8m3 10v-3a7 7 0 0 0-3-6"/>',issues:'<path d="m12 3 10 18H2L12 3Z"/><path d="M12 9v5m0 3v1"/>',departments:'<rect x="8" y="2" width="8" height="6" rx="1"/><path d="M12 8v5M4 13h16M4 13v3m16-3v3M12 13v3"/><rect x="1" y="16" width="6" height="5"/><rect x="9" y="16" width="6" height="5"/><rect x="17" y="16" width="6" height="5"/>',imports:'<path d="M12 16V3m-5 5 5-5 5 5M3 14v7h18v-7"/>',exports:'<path d="M12 3v13m-5-5 5 5 5-5M3 16v5h18v-5"/>',rules:'<path d="M5 3h14v18H5zM8 7h8M8 11h8M8 15h5"/>'};
const navs=[['overview','工作总览'],['imports','数据导入'],['issues','信息核对'],['units','参会单位'],['guests','参会嘉宾'],['departments','邀请进展'],['exports','文件输出'],['rules','统计规则']];
let D,U,G,baseG,edits={},log=[],reviewed={},view='overview',page=1,query='',filter='all',deptGroup='district',sortDir=-1,ruleIndex=0,imported=null,issueMode='pending',guestMode='all';
const STORE='sz-investment-workbench-v1';
function missing(v){let s=String(v??'').trim();return !s||['未知','无','暂无','/','—','-','待补齐','待补充'].includes(s)||/待定|待核对|待确认|待落实|未填报/.test(s)}
const unit=id=>U.get(id),yes=()=>G.filter(g=>g.status==='是'),yesUnits=()=>[...new Set(yes().map(g=>g.unitId))].map(unit),provisional=()=>G.filter(g=>g.status==='空白'||g.status==='待定');
function guestIssues(g){let a=[];if(missing(g.name))a.push('参会人选待落实');if(missing(g.title))a.push('嘉宾职务待补齐');if(missing(g.nationality))a.push('国籍或地区待补齐');return a}
function unitIssues(u){let a=[];if(!['意向投资企业','招商合作机构'].includes(u.type))a.push('单位类型待核对');if(missing(u.country))a.push('单位国别待核对');if(missing(u.industry))a.push('行业待补齐或核对');if(u.type==='意向投资企业'&&missing(u.primaryNature)||u.type==='招商合作机构'&&missing(u.institution))a.push('单位性质待核对');return a}
function allIssues(){return G.filter(g=>g.status!=='否').map(g=>({...g,problems:[...guestIssues(g),...unitIssues(unit(g.unitId)),...(['空白','待定'].includes(g.status)?['参会状态需确认']:[])]})).filter(g=>g.problems.length)}
function save(){try{localStorage.setItem(STORE,JSON.stringify({edits,log,reviewed}));return true}catch(e){toast('浏览器存储不可用，请导出核对草稿保存');return false}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').style.display='none',4000)}
const badge=(s,c='')=>`<span class="badge ${c}">${esc(s)}</span>`,statusBadge=s=>badge(s==='是'?'明确参会':s==='空白'?'空白暂计':s==='待定'?'待定暂计':'不参会',s==='是'?'green':s==='否'?'red':'amber');
function header(title,sub,actions=''){return `<div class="page-head"><div><h1>${title}</h1><div class="subtitle">${sub}</div></div><div class="actions">${actions}</div></div>${Object.keys(edits).length?`<div class="draft-strip"><span>当前有 ${Object.keys(edits).length} 条核对草稿 · 统计为本机试算，尚未形成正式批次</span><button class="linkbtn" data-action="export-drafts">导出草稿</button></div>`:''}`}
function metric(label,value,suffix,detail,tag=''){return `<div class="metric"><div class="label">${label}</div>${tag?`<span class="tag">${tag}</span>`:''}<strong>${value.toLocaleString()}</strong><span class="unit">${suffix}</span><div class="detail">${detail}</div></div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join(''):`<tr><td class="empty" colspan="${headers.length}">没有符合条件的记录</td></tr>`}</tbody></table></div>`}
function pager(n){let last=Math.max(1,Math.ceil(n/20));page=Math.min(page,last);return `<div class="pagination"><span>共 ${n} 条 · 第 ${page} / ${last} 页</span><button data-action="prev" ${page<=1?'disabled':''}>上一页</button><button data-action="next" ${page>=last?'disabled':''}>下一页</button></div>`}
function paged(rows){page=Math.min(page,Math.max(1,Math.ceil(rows.length/20)));return rows.slice((page-1)*20,page*20)}
function departmentRows(group){let ds=D.departments.filter(d=>group==='district'?D.districts.includes(d.label):!D.districts.includes(d.label));return ds.map(d=>{let gs=yes().filter(g=>g.owners.includes(d.label)),us=[...new Set(gs.map(g=>g.unitId))];return{...d,units:us.length,enterprise:us.filter(id=>unit(id).type==='意向投资企业').length,guests:gs.length,rate:us.length/d.target*100}}).sort((a,b)=>sortDir*(a.units-b.units)||b.guests-a.guests)}
function overview(){let gs=yes(),us=yesUnits(),inc=gs.filter(g=>guestIssues(g).length),prior=gs.filter(g=>g.priority).length,counts={};for(let u of us.filter(u=>u.type==='意向投资企业'))counts[u.industry]=(counts[u.industry]||0)+1;let inds=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,5);let ds=departmentRows('district').slice(0,5);return header('工作总览','把分散的填报，整理成可核对、可追溯的参会成果',`<button class="btn" data-nav="imports">导入新表</button><button class="btn primary" data-nav="exports">生成汇报与名单</button>`)+`<div class="notice">当前批次：11月18日汇总名单 · 明确参会与暂计分开披露 · 点击指标下方入口可查看明细</div><div class="metrics">${metric('确认参会单位',us.length,'家',`${us.filter(u=>u.type==='意向投资企业').length} 家企业 · ${us.filter(u=>u.type==='招商合作机构').length} 家机构`,'全市去重')}${metric('确认参会嘉宾',gs.length,'人',`另有 ${provisional().length} 个参会状态待定 / 空白名额`,'明确为“是”')}${metric('重点嘉宾',prior,'人','按榜单、职务及五项完整信息筛选')}${metric('嘉宾资料待完善',inc.length,'条',`涉及 ${new Set(inc.map(g=>g.unitId)).size} 家确认参会单位`,'待核对')}</div><div class="layout"><section class="panel"><div class="panel-head"><h2>各区邀请进展</h2><a href="#departments">查看全部</a></div><div class="panel-body">${ds.map(x=>`<div class="bar-row"><span>${x.label}</span><div class="bar"><span style="width:${Math.min(100,x.rate)}%"></span></div><span class="value">${x.units}<small class="tiny"> 家</small></span></div>`).join('')}<div class="split-note">按确认参会单位排序 · 各区内部去重，跨区成果分别计入</div></div></section><section class="panel"><div class="panel-head"><h2>今天可以先核对</h2><a href="#issues">进入核对</a></div><div class="panel-body">${[['人选未落实',gs.filter(g=>missing(g.name)).length,'人'],['职务待补齐',gs.filter(g=>missing(g.title)).length,'条'],['国籍或地区未知',gs.filter(g=>missing(g.nationality)).length,'人'],['参会状态待确认',provisional().length,'条']].map(([n,v,u])=>`<div class="issue-summary"><div class="issue-label"><span class="dot-icon">!</span>${n}</div><strong>${v}<span class="tiny"> ${u}</span></strong></div>`).join('')}<div class="split-note">一条记录可能同时存在多个问题，分项不可相加。</div></div></section></div><div class="layout"><section class="panel"><div class="panel-head"><h2>企业行业分布</h2><a href="#units">查看企业</a></div><div class="panel-body">${inds.map(([n,v])=>`<div class="bar-row" style="grid-template-columns:170px 1fr 40px"><span>${esc(n)}</span><div class="bar"><span style="width:${v/inds[0][1]*100}%"></span></div><span class="value">${v}</span></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><h2>本批次处理记录</h2><a href="#rules">查看规则</a></div><div class="panel-body"><div class="file-row"><div>原始数据完成清洗<small>保留来源行号、邀请责任单位</small></div>${badge('已载入','green')}</div><div class="file-row"><div>重复姓名按职务择一<small>保留邀请来源，按人去重</small></div>${badge('已应用','green')}</div><div class="file-row"><div>人工核对草稿<small>修改仅保存在当前浏览器</small></div>${badge(Object.keys(edits).length+' 条','amber')}</div></div></section></div>`}
function toolbar(options,extra=''){return `<div class="toolbar"><input class="search" id="search" aria-label="搜索记录" placeholder="搜索企业、嘉宾、职务或邀请单位" value="${esc(query)}"><select id="filter" aria-label="筛选条件">${options.map(([v,l])=>`<option value="${v}" ${filter===v?'selected':''}>${l}</option>`).join('')}</select>${extra}<button class="btn" data-action="clear-search">重置筛选</button></div>`}
function match(g){let u=unit(g.unitId);return [u.name,u.short,g.name,g.title,...g.owners].join(' ').toLowerCase().includes(query.toLowerCase())}
function renderUnits(){let all=yesUnits().filter(u=>(u.name+' '+u.short+' '+u.industry).toLowerCase().includes(query.toLowerCase())).filter(u=>filter==='all'||filter==='company'&&u.type==='意向投资企业'||filter==='institution'&&u.type==='招商合作机构'||filter==='issues'&&unitIssues(u).length);return header('确认参会单位','全市去重单位名单 · 保留企业标准名称、性质及全部邀请来源',`<button class="btn primary" data-action="export-units">导出确认单位Excel</button>`)+`<section class="panel">${toolbar([['all','全部单位'],['company','企业'],['institution','招商合作机构'],['issues','单位资料待完善']])}${table(['参会单位名称','企业 / 机构类型','行业领域','确认嘉宾','邀请来源','操作'],paged(all).map(u=>{let gs=yes().filter(g=>g.unitId===u.id),owners=[...new Set(gs.flatMap(g=>g.owners))];return [`<b>${esc(u.name)}</b><small>${esc(u.short||'简称待补齐')}</small>`,esc(u.type)+`<small>${esc(u.primaryNature||u.institution||'性质待核对')}</small>`,esc(u.industry||'行业待补齐'),`${gs.length} 人`,esc(owners.join('、')),`<button class="linkbtn" data-unit="${u.id}">查看明细</button>`]}))}${pager(all.length)}</section>`}
function renderGuests(){let all=yes().filter(match).filter(g=>filter==='all'||filter==='priority'&&g.priority||filter==='senior'&&g.senior||filter==='incomplete'&&guestIssues(g).length);return header('确认参会嘉宾','参会状态明确为“是” · 同企业同名嘉宾已按规则去重',`<button class="btn primary" data-action="export-guests">导出确认嘉宾Excel</button>`)+`<section class="panel">${toolbar([['all','全部确认嘉宾'],['priority','重点嘉宾'],['senior','总裁及副总裁以上'],['incomplete','嘉宾资料待完善']])}${table(['企业名称','嘉宾姓名','原填职务','国籍 / 地区','邀请来源','操作'],paged(all).map(g=>[esc(unit(g.unitId).name),esc(g.name||'人选未落实')+(edits[g.id]?`<small>已存核对草稿</small>`:''),esc(g.title||'职务待补齐'),esc(g.nationality||'未知'),esc(g.owners.join('、')),`<button class="linkbtn" data-guest="${g.id}">查看 / 核对</button>`]))}${pager(all.length)}</section>`}
function renderIssues(){let full=allIssues(),all=full.filter(match).filter(g=>issueMode==='all'||issueMode==='reviewed'?issueMode==='all'||reviewed[g.id]:!reviewed[g.id]).filter(g=>filter==='all'||filter==='status'&&['空白','待定'].includes(g.status)||filter==='name'&&missing(g.name)||filter==='title'&&missing(g.title)||filter==='nationality'&&missing(g.nationality)||filter==='unit'&&unitIssues(unit(g.unitId)).length);return header('信息核对','先核对问题，再形成可汇报的数据；修改保留原值及来源',`<button class="btn" data-action="export-issues">导出待核对清单</button><button class="btn primary" data-action="export-drafts">导出核对草稿</button>`)+`<div class="notice amber">“已查看”只代表已审阅，不会清除缺失字段。修改嘉宾信息后重新校验；单位资料可在单位详情中核对；企业归并需重新导入并填写名称对照。</div><section class="panel"><div class="tabs">${[['pending','未查看'],['reviewed','已查看'],['all','全部问题']].map(([k,l])=>`<button class="tab ${issueMode===k?'active':''}" data-issue-mode="${k}">${l}</button>`).join('')}</div>${toolbar([['all','全部问题'],['status','参会状态待确认'],['name','人选未落实'],['title','职务待补齐'],['nationality','国籍待补齐'],['unit','单位资料问题']])}${table(['企业 / 嘉宾','参会状态','需核对事项','责任单位','原始行号','操作'],paged(all).map(g=>[esc(unit(g.unitId).name)+`<small>${esc(g.name||'姓名未填')} · ${esc(g.title||'职务未填')}</small>`,statusBadge(g.status),g.problems.map(x=>badge(x,'amber')).join(' '),esc(g.owners.join('、')),esc(g.lines.join('、')),`<button class="linkbtn" data-guest="${g.id}">开始核对</button>`]))}${pager(all.length)}</section>`}
function renderDepartments(){let rows=departmentRows(deptGroup),target=rows.reduce((s,x)=>s+x.target,0),total=rows.reduce((s,x)=>s+x.units,0);return header('邀请进展','确认单位与确认嘉宾分别去重 · 任务完成率按单位数计算',`<button class="btn primary" data-action="export-depts">导出进展Excel</button>`)+`<div class="metrics">${metric('任务指标合计',target,'家','按已确认任务指标')}${metric('部门成果加总',total,'家','含跨部门重复成果')}${metric('任务加总完成率',(total/target*100).toFixed(1),'%','以确认参会单位为分子')}${metric('已完成任务',rows.filter(x=>x.rate>=100).length,'个',rows.filter(x=>x.rate>=100).map(x=>x.label).join('、')||'暂无')}</div><section class="panel"><div class="tabs"><button class="tab ${deptGroup==='district'?'active':''}" data-dept="district">各区级单位</button><button class="tab ${deptGroup==='city'?'active':''}" data-dept="city">市直单位</button></div><div class="toolbar"><span class="tiny">同一企业由多个部门邀请时，分别计入部门成果。</span><button class="btn" data-action="sort-depts">按单位数${sortDir===-1?'降序':'升序'}</button></div>${table(['排名','责任单位','任务指标','确认单位','其中企业','确认嘉宾','完成率'],rows.map((x,i)=>[i+1,esc(x.label),`${x.target} 家`,`${x.units} 家`,`${x.enterprise} 家`,`${x.guests} 人`,badge(x.rate.toFixed(1)+'%',x.rate>=100?'green':'')+`<span class="progress"><i style="width:${x.rate}%"></i></span>`]))}</section><p class="split-note">完成率＝确认参会单位数 ÷ 任务指标。部门成果加总不能作为全市去重总数。</p>`}
function renderImports(){let preview=imported?`<section class="panel" style="margin-top:22px"><div class="panel-head"><h2>导入预览：${esc(imported.name)}</h2>${badge('未计入统计','amber')}</div><div class="panel-body"><p>识别到 ${imported.sheets.length} 个工作表。此处只预览原始记录，不执行企业归并或覆盖当前批次。</p><div class="actions">${imported.sheets.map((s,i)=>`<button class="btn" data-sheet="${i}">工作表 ${i+1} · ${s.rows.length} 行</button>`).join('')}</div></div><div class="preview-table">${table((imported.sheets[imported.selected].rows[0]||[]).slice(0,8).map(x=>esc(x||'未命名列')),imported.sheets[imported.selected].rows.slice(1,16).map(r=>Array.from({length:Math.min(8,imported.sheets[imported.selected].rows[0]?.length||8)},(_,i)=>esc(r[i]||''))))}</div></section>`:'';return header('数据导入','保留每一版源表，再核对新增、变更和缺失信息')+`<div class="workflow"><div><strong>导入源表</strong><small>保留原表与原始行号</small></div><div><strong>预览与检查</strong><small>确认工作表和表头</small></div><div><strong>规则处理</strong><small>后台重算待接入</small></div><div><strong>形成新批次</strong><small>人工核对后发布</small></div></div><section class="panel"><div class="panel-body"><div class="upload-box"><svg viewBox="0 0 24 24"><path d="M12 16V2m-5 5 5-5 5 5M3 15v7h18v-7"/></svg><h2>选择一份新的填报表</h2><p>支持 .xlsx 文件预览，20MB以内。第一版文件在浏览器内解析；导入不会自动覆盖当前统计基线。</p><input id="file-input" type="file" accept=".xlsx" aria-label="选择Excel文件"><span class="tiny" id="import-status"></span></div><div class="file-row"><div>当前正式基线：11月18日汇总名单<small>${D.baseline.units}家确认单位 · ${D.baseline.guests}个确认嘉宾名额 · ${esc(D.baseline.ruleDate)}</small></div>${badge('当前批次','green')}</div></div></section>${preview}`}
function reportText(){let gs=yes(),us=yesUnits(),nat=n=>gs.filter(g=>g.nationality===n).length;return `2026年深圳全球招商大会嘉宾邀请进展（核对稿）\n数据截至：2026年11月18日17:57\n统计说明：${Object.keys(edits).length?'含当前浏览器核对草稿试算，尚未发布正式批次':'依据11月19日规则处理后的确认名单'}。\n一、总体情况\n确认参会单位${us.length}家，其中企业${us.filter(u=>u.type==='意向投资企业').length}家、招商合作机构${us.filter(u=>u.type==='招商合作机构').length}家、类型待核对${us.filter(u=>!['意向投资企业','招商合作机构'].includes(u.type)).length}家。确认参会嘉宾${gs.length}人。\n二、嘉宾情况\n按现有职务筛选结果，总裁及副总裁以上${gs.filter(g=>g.senior).length}条；重点嘉宾${gs.filter(g=>g.priority).length}人。职务改动后的重点及高管标签须重新核定。中国香港${nat('中国香港')}人、中国澳门${nat('中国澳门')}人、中国台湾${nat('中国台湾')}人；国籍或地区身份未知${gs.filter(g=>missing(g.nationality)).length}人。\n三、资料完善\n姓名、职务、国籍至少一项待补齐的确认参会记录${gs.filter(g=>guestIssues(g).length).length}条，已包含在确认参会总人数中。\n四、各区邀请进展\n${departmentRows('district').map(d=>`${d.label}：确认单位${d.units}家、嘉宾${d.guests}人，任务完成率${d.rate.toFixed(1)}%。`).join('\n')}\n五、市直单位邀请进展\n${departmentRows('city').map(d=>`${d.label}：确认单位${d.units}家、嘉宾${d.guests}人，任务完成率${d.rate.toFixed(1)}%。`).join('\n')}\n注：确认口径仅包含参会状态为“是”的记录，人选待定名额按已确认规则计入。部门内部去重，跨部门成果可重复。`}
function renderExports(){let gs=yes();let cards=[['确认参会单位名单','标准名称、简称、单位类型、行业及邀请来源','export-units','XLSX'],['确认参会嘉宾名单','企业全称、企业简称、企业类型、姓名及职务','export-guests','XLSX'],['重点嘉宾名单',`${gs.filter(g=>g.priority).length} 人 · 按现有已核定筛选结果`,'export-priority','XLSX'],['总裁及副总裁以上明细',`${gs.filter(g=>g.senior).length} 条 · 人选附待定记录保留`,'export-senior','XLSX'],['待核对问题清单','参会状态、缺失信息及来源行号','export-issues','XLSX'],['汇报材料核对稿','引用同一批次统计，供人工审阅','export-word','WORD']];return header('文件输出','同一批次生成名单与汇报，保证总数和明细可以核对')+`<div class="notice">Excel按标准Office文件格式生成。处理批次中的重点和高管标签随职务核对自动更新；榜单和职级范围不明确的记录仍需人工复核。</div><div class="export-grid">${cards.map(([n,p,a,t])=>`<section class="export-card"><div class="file-icon ${t==='WORD'?'word':''}">${t}</div><div><h3>${n}</h3><p>${p}</p><button class="btn" data-action="${a}">生成${t==='WORD'?'Word':'Excel'}</button></div></section>`).join('')}</div><section class="panel" style="margin-top:24px"><div class="panel-head"><h2>汇报文字预览</h2><button class="linkbtn" data-action="copy-report">复制全文</button></div><div class="panel-body"><div class="summary-text">${esc(reportText())}</div></div></section>`}
function renderRules(){return header('统计规则','沿用已确认规则文件 · 浏览查看，第一版暂不在线修改规则')+`<div class="rule-select">${D.rules.map((r,i)=>`<button class="btn ${ruleIndex===i?'primary':''}" data-rule="${i}">${esc(r.name.replace('.md',''))}</button>`).join('')}</div><section class="panel"><div class="panel-head"><h2>${esc(D.rules[ruleIndex].name)}</h2><button class="linkbtn" data-action="export-rule">保存规则文件</button></div><div class="rule-text">${esc(D.rules[ruleIndex].text)}</div></section>`}
function render(){view=location.hash.slice(1).split('?')[0]||'overview';if(!navs.some(n=>n[0]===view))view='overview';$('#crumb').textContent=navs.find(n=>n[0]===view)[1];$('#nav').innerHTML=navs.map(([k,l])=>`<a href="#${k}" class="${view===k?'active':''}" title="${l}"><svg viewBox="0 0 24 24">${icons[k]}</svg><span>${l}</span></a>`).join('');$('#main').innerHTML=({overview,units:renderUnits,guests:renderGuests,issues:renderIssues,departments:renderDepartments,imports:renderImports,exports:renderExports,rules:renderRules}[view])();bindInputs()}
function bindInputs(){let q=$('#search');if(q)q.addEventListener('input',e=>{let pos=e.target.selectionStart;query=e.target.value;page=1;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)});$('#filter')?.addEventListener('change',e=>{filter=e.target.value;page=1;render()})}

function drawer(html){$('#drawer').innerHTML=html;$('#drawer').hidden=false;$('#scrim').hidden=false;document.body.style.overflow='hidden';$('#drawer').querySelector('button,input')?.focus()}
function closeDrawer(){$('#drawer').hidden=true;$('#scrim').hidden=true;document.body.style.overflow=''}
function guestDrawer(id){let g=G.find(x=>x.id===id),u=unit(g.unitId),base=baseG.find(x=>x.id===id);drawer(`<div class="drawer-head"><div><h2>嘉宾信息核对</h2><div class="subtitle">${esc(u.name)}</div></div><button data-action="close" aria-label="关闭">×</button></div><div class="source"><h3>来源与当前问题</h3><p>邀请责任单位：${esc(g.owners.join('、'))}</p><p>原表行号：${g.lines.join('、')}</p><p>原姓名：${esc(base.name||'未填')} · 原职务：${esc(base.title||'未填')}</p><p>${[...guestIssues(g),...unitIssues(u)].map(x=>badge(x,'amber')).join(' ')||'关键信息已齐全'}</p></div><form id="guest-form" data-id="${id}"><label class="form-field">嘉宾姓名<input name="name" value="${esc(g.name)}"></label><label class="form-field">嘉宾职务<input name="title" value="${esc(g.title)}"></label><label class="form-field">国籍或地区身份<input name="nationality" value="${esc(g.nationality)}" placeholder="例如：中国、中国香港、日本"></label><label class="form-field">是否参加主会场<select name="status">${['是','待定','空白','否'].map(s=>`<option ${g.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="form-field">核对依据 / 说明<input name="note" required value="${esc(edits[id]?.note||'')}" placeholder="例如：已与邀请部门核实"></label><p class="tiny">保存为本机核对草稿。修改参会状态会更新本机人数试算；职务变更不会自动重判重点或高管标签。</p><div class="drawer-actions"><button class="btn primary" type="submit">保存核对草稿</button><button type="button" class="btn" data-review="${id}">仅标记已查看</button></div>${edits[id]?`<button type="button" class="linkbtn" data-restore="${id}" style="margin-top:20px">恢复本条原始数据</button>`:''}</form>`);$('#guest-form').addEventListener('submit',e=>{e.preventDefault();let fd=new FormData(e.target),patch=Object.fromEntries(fd.entries());for(let k of ['name','title','nationality','note'])patch[k]=patch[k].trim();let changed=Object.keys(patch).some(k=>k!=='note'&&patch[k]!==g[k]);if(!patch.note){toast('请填写核对依据');return}edits[id]=patch;Object.assign(g,patch);reviewed[id]=true;log.push({time:new Date().toISOString(),guest:id,before:{name:base.name,title:base.title,nationality:base.nationality,status:base.status},after:patch});save();closeDrawer();render();toast(changed?'已保存草稿，当前试算已更新':'核对说明已保存')})}
function unitDrawer(id){let u=unit(id),gs=G.filter(g=>g.unitId===id);drawer(`<div class="drawer-head"><div><h2>${esc(u.name)}</h2><div class="subtitle">${esc(u.short||'简称未填')}</div></div><button data-action="close" aria-label="关闭">×</button></div><div class="source"><p>单位类型：${esc(u.type)}</p><p>唯一主分类：${esc(u.primaryNature||u.institution||'待核对')}</p><p>单位国别 / 地区：${esc(u.country)}</p><p>行业领域：${esc(u.industry)}</p><p>原始行号：${esc(u.lines.join('、'))}</p></div><h3 style="margin-top:25px">本单位嘉宾</h3>${gs.map(g=>`<div class="file-row"><div>${esc(g.name||'人选未落实')} ${statusBadge(g.status)}<small>${esc(g.title||'职务待补齐')}</small></div><button class="linkbtn" data-guest="${g.id}">核对</button></div>`).join('')}<p class="split-note">单位资料可在下方核对，邀请来源和原始行号保留。</p>`)}
function guestRows(gs){return gs.map(g=>{let u=unit(g.unitId);return[u.name,g.short||u.short,u.type==='意向投资企业'?u.primaryNature:'机构：'+(u.institution||'待核对'),g.name,g.title]})}
function exportData(a){let file,gs=yes();if(a==='export-guests'||a==='export-priority'||a==='export-senior'){if(a==='export-priority')gs=gs.filter(g=>g.priority);if(a==='export-senior')gs=gs.filter(g=>g.senior);file=Office.xlsx(['企业全称','企业简称','企业类型','嘉宾姓名','嘉宾职务'],guestRows(gs),a==='export-guests'?'确认参会嘉宾名单':a==='export-priority'?'重点嘉宾名单':'总裁及副总裁以上明细')}else if(a==='export-units'){file=Office.xlsx(['企业全称','企业简称','单位类型','企业性质','机构性质','行业领域','确认嘉宾人数','邀请来源'],yesUnits().map(u=>{let g=gs.filter(g=>g.unitId===u.id);return[u.name,u.short,u.type,u.primaryNature,u.institution,u.industry,g.length,[...new Set(g.flatMap(x=>x.owners))].join('；')]}),'确认参会单位名单')}else if(a==='export-issues'){file=Office.xlsx(['企业全称','嘉宾姓名','嘉宾职务','参会状态','待核对事项','邀请来源','原始行号'],allIssues().map(g=>[unit(g.unitId).name,g.name,g.title,g.status,g.problems.join('；'),g.owners.join('；'),g.lines.join('、')]),'待核对问题清单')}else if(a==='export-depts'){file=Office.xlsx(['单位名称','任务指标','确认参会单位','其中企业','确认参会嘉宾','完成率'],departmentRows(deptGroup).map(x=>[x.label,x.target,x.units,x.enterprise,x.guests,x.rate.toFixed(1)+'%']),deptGroup==='district'?'各区邀请进展':'市直单位邀请进展')}else if(a==='export-word')file=Office.docx(reportText(),'嘉宾邀请进展核对稿');else if(a==='export-drafts'){Office.download(new Blob([JSON.stringify({baseline:D.baseline,edits,reviewed,log},null,2)],{type:'application/json'}),'嘉宾核对草稿.json');toast('已导出草稿，原始名单保持不变');return}else if(a==='export-rule'){Office.download(new Blob([D.rules[ruleIndex].text],{type:'text/markdown;charset=utf-8'}),D.rules[ruleIndex].name);return}if(file){Office.download(file.blob,file.name);toast('文件已生成'+(Object.keys(edits).length?'，包含本机核对草稿':''))}}
document.addEventListener('click',async e=>{let b=e.target.closest('button,a');if(!b)return;if(b.dataset.nav){location.hash=b.dataset.nav;return}if(b.dataset.guest){guestDrawer(b.dataset.guest);return}if(b.dataset.unit){unitDrawer(b.dataset.unit);return}if(b.dataset.dept){deptGroup=b.dataset.dept;render();return}if(b.dataset.rule!==undefined){ruleIndex=+b.dataset.rule;render();return}if(b.dataset.sheet!==undefined){imported.selected=+b.dataset.sheet;render();return}if(b.dataset.issueMode){issueMode=b.dataset.issueMode;page=1;render();return}if(b.dataset.review){reviewed[b.dataset.review]=true;save();closeDrawer();render();toast('已标记查看，缺失问题仍保留');return}if(b.dataset.restore){let id=b.dataset.restore;delete edits[id];Object.assign(G.find(g=>g.id===id),baseG.find(g=>g.id===id));save();closeDrawer();render();toast('已恢复原始数据');return}let a=b.dataset.action;if(a?.startsWith('export-')){exportData(a);return}if(a==='close')closeDrawer();if(a==='prev'||a==='next'){page+=a==='prev'?-1:1;render()}if(a==='sort-depts'){sortDir*=-1;render()}if(a==='clear-search'){query='';filter='all';page=1;render()}if(a==='copy-report'){try{await navigator.clipboard.writeText(reportText());toast('汇报文字已复制')}catch{toast('浏览器未允许复制，请手动选择预览文字')}}});
$('#scrim').addEventListener('click',closeDrawer);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer()});$('#help').addEventListener('click',()=>drawer(`<div class="drawer-head"><h2>先从这里检查</h2><button data-action="close" aria-label="关闭">×</button></div><p>1. 在“数据导入”选择实际原始Excel，按规则处理后应用到工作台。</p><p>2. 在“信息核对”修改一条缺失记录，保存核对依据，返回总览检查本机试算。</p><p>3. 在“邀请进展”切换各区与市直单位，检查任务指标和完成率。</p><p>4. 在“文件输出”生成独立Excel和Word核对稿。</p><div class="notice amber">在数据导入页选择原始Excel，处理后点击应用到工作台，再核对和导出。数据保存在本机浏览器，换设备请使用批次备份；多人同步和登录权限尚未接入。</div>`));
window.addEventListener('hashchange',()=>{page=1;query='';filter='all';closeDrawer();render();window.scrollTo(0,0)});
async function init(){try{let r=await fetch('data.json');if(!r.ok)throw Error('数据文件加载失败');D=await r.json();document.querySelector('footer').innerHTML='数据截至 '+esc(D.baseline.date)+' · 规则基线 '+esc(D.baseline.ruleDate)+'<span>原始数据保留，核对修改另存草稿</span>';U=new Map(D.units.map(u=>[u.id,u]));baseG=structuredClone(D.guests);G=structuredClone(baseG);try{let saved=JSON.parse(localStorage.getItem(STORE)||'{}');edits=saved.edits||{};log=saved.log||[];reviewed=saved.reviewed||{};for(let g of G)if(edits[g.id])Object.assign(g,edits[g.id])}catch{toast('草稿读取失败，已载入原始基线')}render()}catch(e){$('#main').innerHTML=`<div class="empty">${esc(e.message)}，请刷新页面重试。</div>`}}
